const message = $input.first().json.message;
const userId = message.from.id;
const userName = message.from.first_name;
const text = message.text || '';
const chatId = message.chat.id;

if (text.startsWith('/start')) {
  return { json: { command: 'start', user_id: userId, user_name: userName, chat_id: chatId } };
}

if (text.startsWith('/help')) {
  return { json: { command: 'help', user_id: userId, user_name: userName, chat_id: chatId } };
}

const category = text.replace('/search', '').trim();
return {
  json: {
    command: 'search',
    user_id: userId,
    user_name: userName,
    chat_id: chatId,
    category: category || 'wireless headphones',
    timestamp: new Date().toISOString()
  }
};

const category = $json.category;
const suppliers = [
  { company_name: 'Yiwu Wholesale Trading Co.', rating: 4.9, years_in_business: 15, moq: '200 pieces', price: 3.80, location: 'Zhejiang, China', verified: true, gold_supplier: true, contact_email: 'export@yiwu-wholesale.com', company_url: 'https://yiwu-wholesale.en.alibaba.com', response_rate: '98%', total_transactions: 12400, product_category: category },
  { company_name: 'Shanghai Premium Exports Inc.', rating: 4.7, years_in_business: 10, moq: '300 pieces', price: 6.50, location: 'Shanghai, China', verified: true, gold_supplier: true, contact_email: 'export@sh-premium.com', company_url: 'https://sh-premium.en.alibaba.com', response_rate: '92%', total_transactions: 7600, product_category: category },
  { company_name: 'Shenzhen Tech Electronics', rating: 4.8, years_in_business: 12, moq: '100 pieces', price: 5.50, location: 'Guangdong, China', verified: true, gold_supplier: true, contact_email: 'sales@shenzhen-tech.com', company_url: 'https://shenzhen-tech.en.alibaba.com', response_rate: '95%', total_transactions: 5800, product_category: category }
];

return suppliers.map(s => ({ json: { ...s, chat_id: $input.first().json.chat_id, user_id: $input.first().json.user_id } }));

const item = $input.first().json;
const chatId = item.chat_id;

const message = `🏢 *${item.company_name}*\n⭐️ ${item.rating}/5 | 📦 MOQ: ${item.moq}\n💰 $${item.price} | 📍 ${item.location}\n📧 ${item.contact_email}\n🌐 ${item.company_url}`;

return { json: { chat_id: chatId, message: message } };
